/* =========================================================
 * Helper functions for the ACF-driven City Landing Page
 * (wrapped in function_exists so they never clash)
 * ========================================================= */

if ( ! function_exists( 'tm_g' ) ) {
    /** Safely read a key from an ACF group array. */
    function tm_g( $arr, $key, $default = '' ) {
        if ( is_array( $arr ) && isset( $arr[ $key ] ) && $arr[ $key ] !== '' && $arr[ $key ] !== null && $arr[ $key ] !== false ) {
            return $arr[ $key ];
        }
        return $default;
    }
}

if ( ! function_exists( 'tm_vals' ) ) {
    /** Return the non-empty text values of a simple ACF group (e.g. tag_1 ... tag_15), in order. */
    function tm_vals( $group ) {
        $out = array();
        if ( is_array( $group ) ) {
            foreach ( $group as $v ) {
                if ( is_string( $v ) && trim( $v ) !== '' ) {
                    $out[] = trim( $v );
                }
            }
        }
        return $out;
    }
}

if ( ! function_exists( 'tm_hl' ) ) {
    /**
     * Print a heading safely and turn [[words]] into a highlighted span.
     * Example field value:  SEO Services in [[Bhubaneshwar]]
     */
    function tm_hl( $text, $class = 'hl' ) {
        $allowed = array(
            'span'   => array( 'class' => array() ),
            'mark'   => array(),
            'br'     => array(),
            'strong' => array(),
            'b'      => array(),
            'em'     => array(),
        );
        $text = wp_kses( (string) $text, $allowed );
        return preg_replace( '/\[\[(.+?)\]\]/s', '<span class="' . esc_attr( $class ) . '">$1</span>', $text );
    }
}

if ( ! function_exists( 'tm_plain' ) ) {
    /** Plain text version of a heading (removes [[ ]] and tags). Used for alt text, titles and schema. */
    function tm_plain( $text ) {
        return trim( wp_strip_all_tags( str_replace( array( '[[', ']]' ), '', (string) $text ) ) );
    }
}

if ( ! function_exists( 'tm_paras' ) ) {
    /**
     * Turn a text / textarea value into paragraphs.
     * Each new line becomes its own <p>. Basic HTML (mark, b, blockquote, div class="flow" ...) is allowed.
     */
    function tm_paras( $text, $class = '' ) {
        $text = trim( (string) $text );
        if ( $text === '' ) {
            return '';
        }
        if ( stripos( $text, '<p' ) !== false || stripos( $text, '<div' ) !== false || stripos( $text, '<blockquote' ) !== false ) {
            return wp_kses_post( $text );
        }
        $cls  = $class ? ' class="' . esc_attr( $class ) . '"' : '';
        $html = '';
        foreach ( preg_split( '/\R+/', $text ) as $line ) {
            $line = trim( $line );
            if ( $line !== '' ) {
                $html .= '<p' . $cls . '>' . wp_kses_post( $line ) . '</p>';
            }
        }
        return $html;
    }
}

if ( ! function_exists( 'tm_img_url' ) ) {
    /** Get an image URL whether ACF returns an ID, an array or a URL. */
    function tm_img_url( $img, $size = 'medium' ) {
        if ( empty( $img ) ) {
            return '';
        }
        if ( is_array( $img ) ) {
            return ! empty( $img['sizes'][ $size ] ) ? $img['sizes'][ $size ] : ( isset( $img['url'] ) ? $img['url'] : '' );
        }
        if ( is_numeric( $img ) ) {
            $url = wp_get_attachment_image_url( (int) $img, $size );
            return $url ? $url : '';
        }
        return (string) $img;
    }
}

if ( ! function_exists( 'tm_img_alt' ) ) {
    /** Get an image's alt text (falls back to the text you pass). */
    function tm_img_alt( $img, $fallback = '' ) {
        $alt = '';
        if ( is_array( $img ) && ! empty( $img['alt'] ) ) {
            $alt = $img['alt'];
        } elseif ( is_numeric( $img ) ) {
            $alt = get_post_meta( (int) $img, '_wp_attachment_image_alt', true );
        }
        return $alt ? $alt : $fallback;
    }
}

if ( ! function_exists( 'tm_icon' ) ) {
    /** Uploaded ACF icon if there is one, otherwise the built-in SVG sprite icon. */
    function tm_icon( $img, $sprite, $style = '' ) {
        $url = tm_img_url( $img, 'thumbnail' );
        $st  = $style ? ' style="' . esc_attr( $style ) . '"' : '';
        if ( $url ) {
            return '<img class="ico ico-img" src="' . esc_url( $url ) . '" alt=""' . $st . ' loading="lazy" />';
        }
        return '<svg class="ico"' . $st . '><use href="#' . esc_attr( $sprite ) . '" /></svg>';
    }
}

