/* FAQ schema is now built from the same ACF FAQs shown on the page */
if ( $faqs ) {
    $schema = array(
        '@context'   => 'https://schema.org',
        '@type'      => 'FAQPage',
        'mainEntity' => array(),
    );
    foreach ( $faqs as $f ) {
        $schema['mainEntity'][] = array(
            '@type'          => 'Question',
            'name'           => wp_strip_all_tags( tm_g( $f, 'faq_question' ) ),
            'acceptedAnswer' => array(
                '@type' => 'Answer',
                'text'  => trim( preg_replace( '/\s+/', ' ', wp_strip_all_tags( tm_g( $f, 'faq_answer' ) ) ) ),
            ),
        );
    }
    echo '<script type="application/ld+json">' . wp_json_encode( $schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . '</script>';
}
